def sample_rc_ccre(seed, pools, genome, backbone_used) -> list[str]:
    """Sample 5K cCRE entries (uniform across all 5 classes), extract
    each, reverse-complement, and return. Excludes backbone_used set
    so RC-cCRE doesn't overlap with the 35K cCRE backbone (preserves
    independence of the 4th component)."""
    rng = random.Random(seed * 4 + 13)
    union_pool = []
    for cls in PRIMARY_CLASSES:
        for chrom, mid in pools[cls]:
            union_pool.append((chrom, mid))
    order = list(range(len(union_pool)))
    rng.shuffle(order)
    seqs = []
    for idx in order:
        if len(seqs) >= N_RC_CCRE:
            break
        chrom, mid = union_pool[idx]
        key = (chrom, mid)
        if key in backbone_used:
            continue
        seq = extract_window(genome, chrom, mid - WIN // 2, rng)
        if seq is None:
            continue
        seqs.append(reverse_complement(seq))
    if len(seqs) < N_RC_CCRE:
        raise RuntimeError(f"seed {seed}: rc-ccre only produced {len(seqs)}/{N_RC_CCRE}")
    return seqs

